import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { build } from 'esbuild'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const target = resolve(root, 'src/terminal/xtermAssets.ts')
const check = process.argv.includes('--check')
// The Android terminal page: xterm.js, its addons and the page's own code, as one script.
const page = await build({
  entryPoints: [resolve(root, 'scripts/terminal-page-entry.ts')],
  bundle: true,
  write: false,
  format: 'iife',
  platform: 'browser',
  target: ['chrome100'],
  minify: true,
  charset: 'utf8',
  legalComments: 'eof',
  sourcemap: false,
  logLevel: 'silent',
})
const css = readFileSync(resolve(root, 'node_modules/@xterm/xterm/css/xterm.css'), 'utf8').replace(/\/\*# sourceMappingURL=.*\*\//g, '')
const generated = [
  '// Generated by scripts/embed-xterm.mjs. Do not edit by hand.',
  `export const TERMINAL_PAGE_JS = ${JSON.stringify(page.outputFiles[0].text)}`,
  `export const XTERM_CSS = ${JSON.stringify(css)}`,
  '',
].join('\n')

let existing = null
try { existing = readFileSync(target, 'utf8') } catch { /* first run */ }
if (check) {
  if (existing !== generated) {
    console.error('Generated xterm assets are stale. Run: node scripts/embed-xterm.mjs')
    process.exitCode = 1
  }
} else if (existing !== generated) {
  mkdirSync(dirname(target), { recursive: true })
  writeFileSync(target, generated)
}
